class Solution:
    def minimumDeleteSum(self, s1, s2):
        from functools import lru_cache
        a = [0] * (len(s1) + 1)
        b = [0] * (len(s2) + 1)
        for i in range(len(s1) - 1, -1, -1):
            a[i] = a[i + 1] + ord(s1[i])
        for j in range(len(s2) - 1, -1, -1):
            b[j] = b[j + 1] + ord(s2[j])
        @lru_cache(None)
        def dfs(i, j):
            if i == len(s1):
                return b[j]
            if j == len(s2):
                return a[i]
            if s1[i] == s2[j]:
                return dfs(i + 1, j + 1)
            return min(ord(s1[i]) + dfs(i + 1, j), ord(s2[j]) + dfs(i, j + 1))
        return dfs(0, 0)

