class Solution:
    def minimumDeleteSum(self, s1, s2):
        m = len(s2)
        dp = [0] * (m + 1)
        for j in range(m - 1, -1, -1):
            dp[j] = dp[j + 1] + ord(s2[j])
        for i in range(len(s1) - 1, -1, -1):
            ndp = [0] * (m + 1)
            ndp[m] = dp[m] + ord(s1[i])
            for j in range(m - 1, -1, -1):
                if s1[i] == s2[j]:
                    ndp[j] = dp[j + 1]
                else:
                    ndp[j] = min(ord(s1[i]) + dp[j], ord(s2[j]) + ndp[j + 1])
            dp = ndp
        return dp[0]

